// Flat-price refs: samples, displays, stain/touch-up kits, casters — no species/construction markups
const FLAT_REFS=new Set(["U2","U3","U4","U5","U6","U7","U8","U9","U10","S45","S46","D17"]);
// Species NOT available for SD 8.5x11 standard sample
const SD_BLOCKED_SP=new Set(["Walnut","Rustic Walnut","Rift White Oak","QS White Oak","TFL","PV","Rauvisio noir Matte HPL","Acrylic HG","Acrylic Matte","Recon White Oak","Recon Walnut"]);
const cp=(item,sp,cx,gDoor,gDrwF,gDrwBox)=>{
  if(isCustom(item.s)){const u=item.p||0;return{u,t:u*item.q,stockBase:u,prePly:u,doorChg:0,dfChg:0,dbChg:0,itemSQ:false,rbsChg:0,plyPct:0};}
  if(FLAT_REFS.has(item.r)&&item.s!=="SD81/2X11"){const u=item.p||0;return{u,t:u*item.q,stockBase:u,prePly:u,doorChg:0,dfChg:0,dbChg:0,itemSQ:false,rbsChg:0,plyPct:0};}
  const s=item.so||sp;const sm=SP[s]||0;const cm=CX[cx]||0;const len=item.len||1;
  const sqin=item.sqin||0;const itemSQ=isSqIn(item.s,item.r);
  const refIceCost=isREF(item.s)&&item.refIce?REF_ICE_CUTOUT:0;
  const isCOItem=isCO(item.s);
  // Use height-specific price for tall cabinets
  const baseP=(item.t==="T"&&item.tallH)?tallPrice(item.s,item.r,item.tallH)||item.p:item.p;
  // EDGT auto-tier: price per sq.in varies by size threshold
  const sqPrice=edgtEffRate(item.s,sqin)??baseP;
  const stockBase=isCOItem?(baseP*(item.sqH||0)*(1+sm/100)):itemSQ?(sqPrice*sqin*(1+sm/100)+refIceCost):(baseP*len*(1+sm/100));
  const ds=item.ds||gDoor||"HNVR";const dInfo=DOORS.find(d=>d.v===ds);
  const dgCharge=dInfo?DG[dInfo.g]||0:0;const dxCharge=dInfo?.x||0;
  const isC3=item.r==="C3";
  const doorChg=(itemSQ&&!isC3||item.t==="M")?0:(dgCharge+dxCharge)*(item.dc||0);
  const drc=item.drc||0;const dfS=item.dfs||gDrwF||"DF-HNVR";
  const dfI=DRW_FRONTS.find(d=>d.v===dfS);const dfgChg=dfI?.g?DFG[dfI.g]||0:0;
  const dfChg=(itemSQ&&!isC3||item.t==="M")?0:dfgChg*drc;
  const oI=OVL_OPTS.find(o=>o.v===_OVL);const ovlChg=(itemSQ&&!isC3||item.t==="M")?0:((oI?.door||0)*(item.dc||0)+(oI?.df||0)*drc);
  const rotQ=(item.rot&&item.rotQ>0)?item.rotQ:0;const rot2Q=(item.rot2&&item.rot2Q>0)?item.rot2Q:0;const brot=item.brot||0;
  const dbI=DRW_BOX.find(d=>d.v===(gDrwBox||"5/8-STD"));const dbChg=isC3?0:(drc+rotQ+rot2Q+brot)*(dbI?.price||0);
  const rbsChg=item.rbs?87:0;
  const prePly=stockBase+doorChg+dfChg+ovlChg+dbChg+rbsChg;
  const u=prePly*(1+cm/100);
  return{u,t:u*item.q,stockBase,prePly,doorChg,dfChg,dbChg,itemSQ,rbsChg,plyPct:cm}};

