const getApplicableMods=(item)=>CABINET_MODS.filter(m=>{
  if(!m.types.includes(item.t))return false;
  if(m.skuMatch&&!m.skuMatch.test(item.s))return false;
  return true;
});
const calcModCost=(item,mods,baseUnitPrice)=>{
  let cost=0;let hasFI=false;
  // FDS is free on tall/base cabinets modified to 18" depth or shallower
  const freeD=mods?.FREE_D;const fdsFree=freeD&&parseInt(freeD)<=18;
  if(mods){CABINET_MODS.forEach(m=>{const v=mods[m.code];if(!v)return;
    if(m.isFI){hasFI=true;return;}// defer FI — computed after all other mods
    if(m.code==="FDS"&&fdsFree)return;// FDS included at no charge for shallow depth
    if(m.pct){cost+=baseUnitPrice*(m.pct/100);}
    else if(m.input==="side"){const sides=v==="B"?2:1;cost+=m.price*sides;}
    else if(m.input==="mxdf"){if(Array.isArray(v))cost+=m.price*v.filter(p=>p.on).length;}
    else if(m.input==="gfd"){if(typeof v==="object"&&v.qty>0){const gs=GFD_STYLES.find(g=>g.v===v.style);cost+=(gs?.price||0)*v.qty;}}
    else if(m.input==="qty_pos"){const qv=typeof v==="object"?v.qty||0:+v||0;cost+=m.price*qv;}
    else{cost+=m.price*(m.input==="check"||m.input==="dims"||m.input==="width"||m.input==="select"?1:+v||0);}
  });}
  if(item.rot&&item.rotQ>0){const ro=ROT_OPTIONS.find(r=>r.v===item.rot);if(ro){cost+=ro.price*item.rotQ;if(item.rotFeg)cost+=72*item.rotQ;}}
  if(item.rot2&&item.rot2Q>0){const ro2=ROT_OPTIONS.find(r=>r.v===item.rot2);if(ro2){cost+=ro2.price*item.rot2Q;if(item.rot2Feg)cost+=72*item.rot2Q;}}
  // FI = 25% of (base + all other mods), excludes door/drawer/drawer system upcharges
  if(hasFI){cost+=(baseUnitPrice+cost)*0.25;}
  return cost;
};


/* ── Cabinet width extractor ─────────────────────────────────
   Strips suffixes (-RT, -FHD, -2D, -1DR, -WS, -MC, -S, -PH, -SS)
   then reads trailing digits as the width. */
function _cabW(sku){
  let s=sku.toUpperCase().replace(/\s+/g,'');
  // Strip depth suffixes for RW cabinets (e.g. RW4230-24 → RW4230)
  s=s.replace(/-(24|27|30)$/,'');
  for(let i=0;i<3;i++)s=s.replace(/-(RT|FHD|2D|2DR|1DR|WS|MC|SS|PH|S)$/,'');
  const m=s.match(/(\d+)$/);if(!m)return 0;
  const n=parseInt(m[1]);
  // If number is a valid width on its own (9–84), use it directly
  if(n>=9&&n<=84)return n;
  // Otherwise it's concatenated width+height (e.g. "1230" = 12 wide × 30 tall)
  // — strip the last 2 digits (height) to get the width
  const ds=m[1];
  if(ds.length>=3){const w=parseInt(ds.slice(0,ds.length-2));return(w>=9&&w<=84)?w:0;}
  return 0;
}

