/* Default tall heights for refs not explicitly listed */
const TALL_H_DEFAULT=[84,87,90,93,96,102,108,114];
function tallHeights(ref){return TALL_HEIGHTS[ref]||TALL_H_DEFAULT;}
// Look up exact price for a tall/oven SKU at a given height; falls back to base (84″) price
function tallPrice(sku,ref,height){
  const prices=TALL_P[sku];if(!prices)return null;
  const hts=tallHeights(ref);
  const idx=hts.indexOf(height);
  if(idx<0||idx>=prices.length)return prices[0];// fallback to 84″
  return prices[idx];
}

/* ── RW cabinet depth extractor (24, 27, or 30) ────────── */
function _rwDepth(sku){
  const m=sku.match(/-(24|27|30)$/);
  return m?parseInt(m[1]):0;
}
/* ── RW cabinet height extractor ────────── */
function _rwH(sku){
  let s=sku.toUpperCase().replace(/\s+/g,'');
  // Strip depth suffix (e.g. RW4230-24 → RW4230)
  s=s.replace(/-(24|27|30)$/,'');
  // Match the trailing number after RW prefix (e.g. RW4230 → 4230)
  const m=s.match(/^RW(\d+)$/);if(!m)return 0;
  const ds=m[1];
  // Concatenated width+height: last 2 digits are height (e.g. 4230 → 30)
  if(ds.length>=4){return parseInt(ds.slice(-2));}
  return 0;
}

/* ── Cabinet height extractor (for tall cabinets) ────────── */
function _cabH(sku,typeCode){
  if(typeCode!=="T")return 0;
  let s=sku.toUpperCase().replace(/\s+/g,'');
  for(let i=0;i<3;i++)s=s.replace(/-(RT|FHD|2D|2DR|1DR|WS|MC|SS|PH|S)$/,'');
  const m=s.match(/(\d+)$/);if(!m)return 0;
  const ds=m[1];
  // Concatenated width+height (e.g. "2484" = 24 wide × 84 tall, "3093" = 30 wide × 93 tall)
  if(ds.length>=4){const h=parseInt(ds.slice(-2));if(h>=80&&h<=99)return h;
    // 3-digit heights like 102, 108, 114
    const h3=parseInt(ds.slice(-3));if(h3>=100&&h3<=120)return h3;}
  // Default: 84" base height (other heights selectable via height picker)
  return 84;
}

/* ── guessDoors ────────────────────────────────────────────── */
function guessDoors(sku,typeCode){
  const s=sku.toUpperCase().replace(/\s+/g,'');
  // Non-cabinet types (A,G,M,S,X) — 0 doors
  if(typeCode&&!'BVTW'.includes(typeCode))return 0;
  // === Zero-door types ===
  if(/^(BBBD\dD|BBD\dD|BBB\dD|B[2-5]D|STB4D)/.test(s))return 0;
  if(/^(FLVB\dD|VTB\dD|VB\dD)/.test(s))return 0;
  if(/^(F[36]|EFIL|ECROWN|ETOEKICK|RBS|BNFT|FRLG|SMF|SBAF|EDIK|SMP|LCEC|TKLC)/.test(s))return 0;
  if(/^(RH|PRH)/.test(s))return 0;
  // Mud Room Top (MRT) — open shelves, no doors
  if(/^MRT\d/.test(s)&&!/^MRTD/.test(s))return 0;
  // Mud Room Top w/ Doors (MRTD) — 1 door up to 24"W, 2 doors for -2D and wider
  if(/^MRTD/.test(s)){if(s.includes('-2D'))return 2;const w=_cabW(sku);return w>24?2:1;}
  // Mud Room Drawer Base w/ Door (MRDBD) — drawer only, no doors
  if(/^MRDBD/.test(s))return 0;
  // BUBO (Utensil Bin Organizer) — 1 door
  if(/^BUBO/.test(s))return 1;
  // VTCSD (Vanity Tall Combination Sink Drawer) — 1 door (24-36"W), 2 doors for -2D (39-48"W)
  if(/^VTCSD/.test(s)){if(s.includes('-2D'))return 2;return 1;}
  // Drawer-only ADA types
  if(/^(BA[2-5]D|BA2HD|VBA\dD)/.test(s))return 0;
  if(/^FLVB\d+HD/.test(s))return 0;
  if(/^SFDHD/.test(s))return 0;
  // === Utility/Tall 2-section types ===
  if(/^(UVTD|UVD)\d/.test(s)){if(s.includes('-2D'))return 2;const w=_cabW(sku);return(w>24)?2:1;}
  if(/^(UVTH|UVH)\d/.test(s))return 2;
  if(/^(UVT|UV)\d/.test(s)){if(s.includes('-2D'))return 4;const w=_cabW(sku);return(w>24)?4:2;}
  // === Suffix-based ===
  if(s.includes('-2D'))return 2;
  if(s.includes('FHD')){const w=_cabW(sku);return w>24?2:1;}
  // === Specific types ===
  if(/^(BBC|SBBC|PBBC)/.test(s))return 1;
  if(/^(BLE|BLSBE|BLSB|BL)/.test(s))return 2;
  if(/^TB\d/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  if(/^(B2HD|B2TD)/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  if(/^BBB\d/.test(s)&&!/^BBB\dD/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  if(/^(VTSD|VSD)/.test(s))return 2;
  // === Width-based for std bases/sink/vanity/peninsula ===
  if(/^(?:BA|B|SBA|SBR|SBU|SB|PB|VBA|VB|VTB|FLVB|VSBR|VSB|VTSBR|VTSB|VCSD|VBW|VTBW|VBH|VTHB|VGO|VO)\d/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  // Utility / Tall — 2 sections, width-based
  if(/^(U\d|UT\d|CP)/.test(s)){if(s.includes('-2D'))return 4;const w=_cabW(sku);return(w>24)?4:2;}
  // === Dressing Room (all TypeCode V) ===
  if(/^VTC/.test(s))return 0;
  if(/^(DRBOS|PDRBOS|DRUS|DRSU|DRSSU|DRAUS|DRARUS|DRCSU|DRSCSU|DRCR|DRFL|DRM-|DRSH|DREP|CBSK|PDCR)/.test(s))return 0;
  if(/^DRB3D/.test(s))return 0;
  if(/^(DRU5D|DRU5TO|DRU5JO|DRU3CR|DRU4D)/.test(s))return 1;
  if(/^(DRTRU|DRDHU|DRMHU|DRTHU|DRPDRU)/.test(s))return 2;
  if(/^DRLDU/.test(s)){if(s.includes('-2D'))return 4;return 2;}
  if(/^DRTRB/.test(s))return 1;
  if(/^(PDRBD|DRBD)/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  if(/^(PDRBDO|DRBDO|DRSB)/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  // Wall cabinets — width-based
  if(/^W\d/.test(s)){const w=_cabW(sku);return w>24?2:1;}
  if(s.startsWith('WBC'))return 1;
  return 1;
}

/* ── guessDrawers ──────────────────────────────────────────── */
function guessDrawers(sku,typeCode){
  const s=sku.toUpperCase().replace(/\s+/g,'');
  if(!'BVT'.includes(typeCode))return 0;
  if(typeCode==='T')return 0;
  // === Utility vanity types (TypeCode V) ===
  if(/^(UVTD|UVD)\d/.test(s))return 3;
  if(/^(UVTH|UVH|UVT|UV)\d/.test(s))return 0;
  if(/^SFDHD/.test(s))return 2;
  // Mud Room Top (MRT/MRTD) — no drawers
  if(/^MRT/.test(s))return 0;
  // MRDBD — 1 drawer, no doors
  if(/^MRDBD/.test(s))return 1;
  // BUBO — no drawers (utensil bin organizer)
  if(/^BUBO/.test(s))return 0;
  // VTCSD — 2 drawers (24-36"W), 1 drawer for -2D (39-48"W)
  if(/^VTCSD/.test(s)){return s.includes('-2D')?1:2;}
  // === Dressing Room (all TypeCode V) ===
  if(/^VTC/.test(s))return 0;
  if(/^(DRU5D|DRU5TO|DRU5JO)/.test(s))return 5;
  if(/^DRU4D/.test(s))return 4;
  if(/^DRU3CR/.test(s))return 3;
  if(/^DRB3D/.test(s))return 3;
  if(/^(PDRBD|DRBD)/.test(s))return 1;
  if(/^DR/.test(s))return 0;
  // === Zero-drawer base/vanity types ===
  if(s.includes('FHD'))return 0;
  if(/^TB\d/.test(s))return 0;
  if(/^(BLE|BLSBE|BLSB|BL)/.test(s))return 0;
  if(/^(VSB|VSBR)\d/.test(s))return 1;
  if(/^(VGO|VO)\d/.test(s))return 0;
  // === Multi-drawer extraction ===
  const bbbd=s.match(/^BBBD(\d)D/);if(bbbd)return parseInt(bbbd[1]);
  const bbd=s.match(/^BBD(\d)D/);if(bbd)return parseInt(bbd[1]);
  const bbb=s.match(/^BBB(\d)D/);if(bbb)return parseInt(bbb[1]);
  const bd=s.match(/^B(\d)D/);if(bd)return parseInt(bd[1]);
  if(s.startsWith('STB4D'))return 4;
  if(s.startsWith('B2TD'))return 2;
  if(s.startsWith('B2HD'))return 2;
  const bad=s.match(/^(?:VBA|BA)(\d)D/);if(bad)return parseInt(bad[1]);
  if(s.startsWith('BA2HD'))return 2;
  const flvbhd=s.match(/^FLVB(\d+)HD/);if(flvbhd)return parseInt(flvbhd[1]);
  const flvb=s.match(/^FLVB(\d)D/);if(flvb)return parseInt(flvb[1]);
  const vtb=s.match(/^VTB(\d)D/);if(vtb)return parseInt(vtb[1]);
  const vb=s.match(/^VB(\d)D/);if(vb)return parseInt(vb[1]);
  if(s.startsWith('VTSD'))return 2;
  if(s.startsWith('VSD'))return 2;
  if(/-2DR/.test(s))return 2;
  if(/-1DR/.test(s))return 1;
  if(/^(BBC|SBBC|PBBC)/.test(s))return 1;
  const w=_cabW(sku);
  if(w>0){if(/^(BA|B|SBA|SBR|SBU|SB|PB|BBB)/.test(s)){return w>24?2:1;}}
  if(w>0){if(/^(VB|VTB|VTSB|FLVB|VBW|VTBW|VBH|VTHB|VCSD)/.test(s)){return w>24?2:1;}}
  if(typeCode==='B'||typeCode==='V')return 1;
  return 0;
}

/* ── guessBuiltInROT ─── built-in roll-out trays from SKU ── */
function guessBuiltInROT(sku){
  const s=sku.toUpperCase().replace(/\s+/g,'');
  if(/-RT/.test(s)){
    if(/^SB/.test(s))return 1;
    if(/^B/.test(s))return 2;
  }
  if(/^SBU\d/.test(s))return 1;
  return 0;
}
